type RenderAuditResult struct {
	...
	Summary struct {
		Pages         int  `json:"pages"`
		...
		PagesTotal    int  `json:"pages_total,omitempty"`
		Truncated     bool `json:"truncated,omitempty"`
+		// PagesAudited names the pages SUCCESSFULLY MEASURED. Pages counts
+		// pages ATTEMPTED, so len(PagesAudited) < Pages exactly when a page
+		// is Unreachable. A REPAIRED page reports nothing and is otherwise
+		// indistinguishable from one never visited — which is why the
+		// audited set cannot be derived from the findings.
+		PagesAudited []string `json:"pages_audited,omitempty"`
	} `json:"summary"`
}

// Execute, inside the URL loop:
 	if err != nil {
 		res.Unreachable = append(res.Unreachable, url)
 		failedPages[url] = true
 		continue
 	}
+	// Past the reachability guard, so this page WAS measured.
+	res.Summary.PagesAudited = append(res.Summary.PagesAudited, url)

// mirrored summary gains PagesAudited []string `json:"pages_audited"`
+batchID := uuid.New()   // set on every filed item; makes the closer's guard live

 // after the insert loop, before Commit:
+retracted, retractedParked, rErr := retractResolvedContrastFindings(ctx, tx, siteID, batchID, payload, logger)

+func retractResolvedContrastFindings(...) (retracted, parked int, err error) {
+	if len(payload.Summary.PagesAudited) == 0 { return 0, 0, nil }  // old-shape reply: INERT
+	// one key PREFIX per audited page — keeps '#' inside the comparison so
+	// "/blog" cannot match a key belonging to "/blog.html"
+	for _, u := range payload.Summary.PagesAudited { ... workItemKey("contrast_failure", urlPath(u)+"#") }
+	// every pairing measured as failing — firm AND over_image, BEFORE the
+	// locked skip and BEFORE the max_items cap
+	for _, c := range payload.Contrast {
+		stillFailing[workItemKey("contrast_failure", urlPath(c.URL)+"#"+contrastSelector(c.Tag, c.Class))] = true
+	}
+	// read open rows and CLOSE THE CURSOR before any UPDATE (one Tx = one conn)
+	SELECT COALESCE(item_key,''), status FROM site_work_items
+	 WHERE site_id=$1 AND item_type='contrast_failure' AND status NOT IN (<closed>)
+	for each row: skip if stillFailing[key]; skip if no audited-page prefix matches;
+		resolveWorkItems(ctx, tx, siteID, "render_audit", batchID,
+			checks.ResolvedFinding{ItemType: "contrast_failure", ItemKey: key, Reason: ...}, logger)
+}

